import java.util.NavigableSet;
import java.util.TreeSet;

public class FlightCorridorController {
    private final NavigableSet<Integer> occupiedAltitudes = new TreeSet<>();

    public void registerAltitude(int altitude) {
        occupiedAltitudes.add(altitude);
    }

    public Integer findClosestHigherAltitude(int target) {
        return occupiedAltitudes.higher(target);
    }

    public Integer findClosestLowerAltitude(int target) {
        return occupiedAltitudes.lower(target);
    }

    public static void main(String[] args) {
        FlightCorridorController controller = new FlightCorridorController();
        controller.registerAltitude(10000);
        controller.registerAltitude(12000);
        controller.registerAltitude(15000);
        controller.registerAltitude(20000);

        int emergencyAltitude = 13500;
        System.out.println("Flight requesting clearance at: " + emergencyAltitude + " ft");
        System.out.println("Immediate higher traffic at:    " + controller.findClosestHigherAltitude(emergencyAltitude) + " ft");
        System.out.println("Immediate lower traffic at:     " + controller.findClosestLowerAltitude(emergencyAltitude) + " ft");
    }
}

