import java.util.TreeSet;

public class HotelBookingEngine {
    public static int findClosestHigherOrEqual(int[] prices, int budget) {
        if (prices == null || prices.length == 0) return -1;
        TreeSet<Integer> set = new TreeSet<>();
        for (int p : prices) set.add(p);
        Integer match = set.ceiling(budget);
        return match != null ? match : -1;
    }
}

