import java.util.TreeSet;

public class TimestampBoundSearch {
    public static int[] findBounds(int[] timestamps, int target) {
        if (timestamps == null || timestamps.length == 0) return new int[]{-1, -1};
        TreeSet<Integer> set = new TreeSet<>();
        for (int t : timestamps) set.add(t);

        Integer f = set.floor(target);
        Integer c = set.ceiling(target);
        return new int[]{f != null ? f : -1, c != null ? c : -1};
    }
}
